<template>
	<view>
		<scroll-view scroll-y="true" class="SV_categoryTitle">
			<view class="categoryTitle">
				<view class="categoryName" v-for="(item, index) in categoryList" :key="index" :class="categoryNameActive == index ? 'categoryNameActive' : ''" @click="categoryClickEvent(item, index)">
					{{ item.name }}
				</view>
			</view>
		</scroll-view>
		<scroll-view class="scroll-Y" :scroll-y="true" :scroll-top="scrollTop" :scroll-with-animation="true" @scroll="scrollEvent">
			<view class="categoryList" v-for="(item, index) in categoryList" :key="item.id">
				<view class="categoryListName">{{ item.name }}</view>
				<view class="categoryListBox">
					<view class="item-text" v-for="(sub, idx) in item.subCategoryList" :key="idx">{{ sub.name }}</view>
				</view>
			</view>
		</scroll-view>
	</view>
</template>

<script>
import { getTotalInfo } from '@/util/api';
export default {
	data() {
		return {
			categoryList: [],
			categoryNameActive: 0, //当前选中active
			scrollTop: 0, //scroll-top
			scrollVal: 0, //滑动的值
			scrollStatus: true, //点击状态，是否能点击
			nodeHeight: [], //存储categoryList的top
			windowHeight: 0,
			windowTop: 0,
		};
	},
	mounted() {
		uni.getSystemInfo({
			success: (res) => {
				this.windowHeight = res.windowHeight;
				this.windowTop = res.windowTop;
			}
		});
		this.nodeHeight = [];
		let theNode = uni.createSelectorQuery().in(this).selectAll(".categoryList");
		theNode.boundingClientRect((data) => {
			data.forEach((item, index) => {
				// #ifndef H5
				this.nodeHeight.push({
					top: item.top,
					index: index
				})
				// #endif
				// #ifdef H5
				this.nodeHeight.push({
					top: item.top + this.windowTop,
					index: index
				})
				// #endif
			})
		}).exec()
	},
	onLoad() {
		this.getTotalInfo()
	},
	methods: {
		getTotalInfo(){
			let lineData = uni.getStorageSync('line')
			let params = {
				lineId: lineData.id,
				startTime : "2025-05-17 00:00:00",
				endTime: "2025-05-17 23:59:59"
			}
			getTotalInfo(params).then(res => {
				if (res.code == 200) {
					
				}
			})
		},
		categoryClickEvent(item, index) {
			// 300毫秒才能执行下次点击
			if (this.scrollStatus) {
				this.scrollStatus = false;
				this.categoryNameActive = index;
				let theNode = uni.createSelectorQuery().in(this).selectAll(".categoryList");
				theNode.boundingClientRect((data) => {
					/* 获取当前第index的categoryList的top,滑动后值scrollVal + categoryList的top */
					// #ifndef H5
					this.scrollTop = this.scrollVal + data[index].top;
					// #endif
					// #ifdef H5
					this.scrollTop = this.scrollVal + data[index].top + this.windowTop;
					// #endif
					setTimeout(() => {
						// 200毫秒才能执行下次点击
						this.scrollStatus = true;
					}, 200)
				}).exec()
			}
		},
		scrollEvent(e) {
			if (this.scrollVal < e.detail.scrollTop) {
				// 向上
				this.nodeHeight.forEach(item => {
					if (this.scrollVal - item.top < 0 && this.scrollVal - item.top > -this.windowHeight) {
						this.categoryNameActive = item.index;
					}
				})
			} else {
				// 向下
				this.nodeHeight.forEach(item => {
					if (this.scrollVal - item.top > 0 && this.scrollVal - item.top < this.windowHeight) {
						this.categoryNameActive = item.index;
					}
				})
			}
			this.scrollVal = e.detail.scrollTop;
		},
	},
}
</script>

<style scoped lang="scss">
.item-text {
	width: 100%;
}

.categoryTitle {
	width: 249rpx;
	float: left;
	height: 100vh;
	background: #f7f9fa;
}

.SV_categoryTitle {
	width: 250rpx;
	height: 100vh;
	float: left;
}

.categoryName {
	width: 100%;
	text-align: center;
	height: 100rpx;
	line-height: 100rpx;
	color: #3E3E3E;
	background: #f7f9fa;
}

.categoryNameActive {
	background: #fff;
}

.scroll-Y {
	height: 100vh;
	width: 500rpx;
	float: left;
}

.categoryList {
	width: 100%;
	box-sizing: border-box;
	height: 100vh;
}

.categoryListName {
	width: 100%;
	height: 100rpx;
	line-height: 100rpx;
	color: #4892e9;
	background: #eef9fd;
	padding-left: 26rpx;
	float: left;
}

.categoryListBox {
	float: left;
	overflow: hidden;
	padding-left: 26rpx;

}

.item-text {
	color: #000;
	font-size: 28rxp;
	font-weight: 500;
	padding: 24rpx 0;
}

.categoryListBox image {
	width: 145rpx;
	height: 145rpx;
}

.categoryListName_line {
	height: 30rpx;
	background: rgba(0, 126, 96, 0.7);
	width: 8rpx;
	float: left;
	margin-top: 35rpx;
}
</style>
